import React, { useEffect, useRef, useState } from "react";





const IMG = {
  tropical: "data:image/webp;base64,",
  cherry: "data:image/webp;base64,",
  berries: "data:image/webp;base64,",
  ruby: "data:image/webp;base64,",
  pack: "data:image/webp;base64,",
};

const products = [
  { id: "tropical", name: "TROPICAL TANGERINE", image: IMG.tropical, accent: "#c7c11f" },
  { id: "cherry", name: "LUSH CHERRY", image: IMG.cherry, accent: "#e29bbd" },
  { id: "berries", name: "WILD BERRIES", image: IMG.berries, accent: "#3d1f5c" },
  { id: "ruby", name: "RUBY ORANGE", image: IMG.ruby, accent: "#8a2c1a" },
  { id: "10032", name: "variety pack", image: IMG.pack, accent: "#e2472b" },
];

export default function ProductCarouselPreview() {
  const [hovered, setHovered] = useState(null);
  const [start, setStart] = useState(0);
  const [step, setStep] = useState(0);
  const [visibleCount, setVisibleCount] = useState(4);
  const [isDragging, setIsDragging] = useState(false);
  const [dragOffset, setDragOffset] = useState(0);

  const viewportRef = useRef(null);
  const trackRef = useRef(null);
  const dragStartX = useRef(0);

  const headingRef = useRef(null);
  const [headingVisible, setHeadingVisible] = useState(false);

  useEffect(() => {
    const node = headingRef.current;
    if (!node) return;

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setHeadingVisible(true);
          observer.disconnect();
        }
      },
      { threshold: 0.4 }
    );

    observer.observe(node);
    return () => observer.disconnect();
  }, []);

  const maxStart = Math.max(0, products.length - visibleCount);

  useEffect(() => {
    const measure = () => {
      const track = trackRef.current;
      const viewport = viewportRef.current;
      const firstCard = track?.children?.[0];
      if (!track || !viewport || !firstCard) return;

      const cardWidth = firstCard.getBoundingClientRect().width;
      const gap = parseFloat(getComputedStyle(track).columnGap || "0");
      const viewportWidth = viewport.getBoundingClientRect().width;

      setStep(cardWidth + gap);
      setVisibleCount(
        Math.max(1, Math.round((viewportWidth + gap) / (cardWidth + gap)))
      );
    };

    measure();
    window.addEventListener("resize", measure);
    return () => window.removeEventListener("resize", measure);
  }, []);

  useEffect(() => {
    setStart((current) => Math.min(current, maxStart));
  }, [maxStart]);

  const previous = () => {
    setStart((current) => (current <= 0 ? maxStart : current - 1));
  };

  const next = () => {
    setStart((current) => (current >= maxStart ? 0 : current + 1));
  };

  const handlePointerDown = (event) => {
    dragStartX.current = event.clientX;
    setIsDragging(true);
    setDragOffset(0);
  };

  const handlePointerMove = (event) => {
    if (!isDragging) return;
    setDragOffset(event.clientX - dragStartX.current);
  };

  const endDrag = () => {
    if (!isDragging) return;
    const threshold = step / 4 || 40;
    if (dragOffset > threshold) previous();
    else if (dragOffset < -threshold) next();
    setIsDragging(false);
    setDragOffset(0);
  };

  const trackOffset = start * step - dragOffset;

  return (

    
    <section className="product-carousel">
      <style>{`
        .product-carousel {
          --cream: #fbf4ec;
          --purple: #2c124c;
          --carousel-gap: clamp(20px, 3.2vw, 60px);
          --visible: 4;
          position: relative;
          width: 100%;
          box-sizing: border-box;
          padding: 18px 5vw 34px;
          overflow: hidden;
          background: var(--cream);
          color: var(--purple);
          font-family: Georgia, "Times New Roman", serif;
          
        }
        .product-carousel *, .product-carousel *::before, .product-carousel *::after { box-sizing: border-box; }
        .product-carousel__top { position: relative; min-height: 110px; }
        .product-carousel__top h2 {
          margin: 0 auto; width: min(720px, 60vw); text-align: center;
          font-size: clamp(24px, 3vw, 46px); line-height: 0.9;
          letter-spacing: -0.04em; font-weight: 800;
        }
        .product-carousel__navigation { position: absolute; top: 8px; right: 0; display: flex; gap: 5px; }
        .carousel-arrow {
          width: 50px; height: 50px; border: 2px solid var(--purple); border-radius: 50%;
          background: transparent; color: var(--purple); display: grid; place-items: center;
          cursor: pointer; font-family: Arial, sans-serif;
          transition: background-color 220ms ease, color 220ms ease, transform 220ms ease;
        }
        .carousel-arrow span { display: block; font-size: 22px; line-height: 1; transform: translateY(-2px); }
        .carousel-arrow:hover { transform: scale(1.06); background: var(--purple); color: var(--cream); }
        .carousel-arrow--filled { background: var(--purple); color: var(--cream); }
        .carousel-arrow--filled:hover { background: transparent; color: var(--purple); }
        .product-carousel__viewport { width: 100%; overflow: hidden; padding-top: 36px; }
        .product-carousel__track {
          display: flex; align-items: flex-start; gap: var(--carousel-gap);
          transition: transform 550ms cubic-bezier(0.16, 1, 0.3, 1);
          touch-action: pan-y; cursor: grab;
        }
        .product-carousel__track--dragging { transition: none; cursor: grabbing; }
        .product-card {
          flex: 0 0 calc((100% - (var(--visible) - 1) * var(--carousel-gap)) / var(--visible));
          min-width: 0; text-align: center; cursor: pointer;
        }
        .product-card__visual {
          position: relative; height: 230px; display: flex; justify-content: center;
          align-items: center; isolation: isolate;
        }
        .product-card__blob {
          position: absolute; z-index: -1; width: 50%; aspect-ratio: 1; border-radius: 50%;
          background: var(--accent); opacity: 0; transform: scale(0.7);
          transition: opacity 350ms ease, transform 500ms cubic-bezier(0.16, 1, 0.3, 1);
        }
        .product-card__image {
          display: block; height: 210px; max-width: 88%; object-fit: contain;
          transform: translateY(0) rotate(0deg) scale(1); transform-origin: 50% 82%;
          filter: drop-shadow(0 10px 7px rgba(38, 18, 58, 0.16));
          transition: transform 480ms cubic-bezier(0.16, 1, 0.3, 1), filter 300ms ease;
          user-select: none;
        }
        .product-card:hover .product-card__image, .product-card.is-active .product-card__image {
          transform: translateY(-7px) rotate(4deg) scale(1.035);
          filter: drop-shadow(0 18px 12px rgba(38, 18, 58, 0.22));
        }
        .product-card:hover .product-card__blob, .product-card.is-active .product-card__blob {
          opacity: 1; transform: scale(1);
        }
        .product-card h3 {
          min-height: 40px; margin: 2px 0 18px; padding: 0 8px;
          font-size: clamp(16px, 1.8vw, 24px); line-height: 0.98;
          letter-spacing: -0.03em; font-weight: 800; text-transform: uppercase;
        }
        .quick-add-stage {
          --cta-stage-w: 210px;
          --cta-pill-w: 96px;
          --cta-pill-h: 46px;
          --cta-pill-left: 67px;
          --cta-circle: 46px;
          --cta-rest-x: 164px;
          --cta-active-x: 22px;
          position: relative; width: var(--cta-stage-w); max-width: 100%; height: 56px;
          margin: 0 auto; display: flex; align-items: center;
        }
        .quick-add-pill {
          position: absolute; left: var(--cta-pill-left); top: 50%; transform: translateY(-50%);
          z-index: 2; width: var(--cta-pill-w); height: var(--cta-pill-h); padding: 0;
          border-radius: 999px; background: var(--cream); border: 2px solid var(--purple);
          color: var(--purple); font-family: Arial, Helvetica, sans-serif; font-weight: 800;
          font-size: 13px; letter-spacing: 0.02em; white-space: nowrap; cursor: pointer;
          user-select: none; display: flex; align-items: center; justify-content: center;
        }
        .quick-add-morph {
          position: absolute; top: 50%; left: 0; width: var(--cta-circle); height: var(--cta-circle);
          padding: 0; border-radius: 50%; border: 2px solid var(--purple); background: var(--cream);
          display: flex; align-items: center; justify-content: center; cursor: pointer; z-index: 1;
          transform: translate(var(--cta-rest-x), -50%);
          transition: transform 0.4s cubic-bezier(0.34,1.6,0.64,1), background 0.4s cubic-bezier(0.34,1.6,0.64,1);
        }
        .quick-add-stage:hover .quick-add-morph, .quick-add-stage.is-active .quick-add-morph {
          transform: translate(var(--cta-active-x), -50%); background: var(--purple);
        }
        .quick-add-morph svg { width: 18px; height: 18px; transition: transform 0.4s cubic-bezier(0.34,1.6,0.64,1); }
        .quick-add-arrow { stroke: var(--purple); transition: stroke 0.4s ease; }
        .quick-add-stage:hover .quick-add-arrow, .quick-add-stage.is-active .quick-add-arrow { stroke: var(--cream); }
        .quick-add-stage:hover .quick-add-morph svg, .quick-add-stage.is-active .quick-add-morph svg { transform: rotate(45deg); }
        @media (max-width: 640px) {
          .product-carousel { --visible: 2; --carousel-gap: 14px; }
          .quick-add-stage {
            --cta-stage-w: 168px; --cta-pill-w: 77px; --cta-pill-h: 37px; --cta-pill-left: 54px;
            --cta-circle: 37px; --cta-rest-x: 131px; --cta-active-x: 17px; height: 44px;
          }
        }
        .stagger-heading .stagger-word {
          display: inline-block;
          opacity: 0;
          transform: translateY(0.4em);
          will-change: transform, opacity;
        }
        .stagger-heading.is-visible .stagger-word {
          animation: stagger-word-in 0.6s cubic-bezier(0.16, 1, 0.3, 1) forwards;
          animation-delay: var(--stagger-delay, 0s);
        }
        @keyframes stagger-word-in {
          to {
            opacity: 1;
            transform: translateY(0);
          }
        }
        @media (prefers-reduced-motion: reduce) {
          .stagger-heading .stagger-word {
            animation: none;
            opacity: 1;
            transform: none;
          }
        }
      `}</style>

      <div className="product-carousel__top">
        <h2 className={`stagger-heading${headingVisible ? " is-visible" : ""}`} ref={headingRef}>
          {"DRINKS AS DELICIOUS".split(" ").map((word, i) => (
            <span
              key={`l1-${i}`}
              className="stagger-word"
              style={{ "--stagger-delay": `${i * 0.08}s` }}
            >
              {word}&nbsp;
            </span>
          ))}
          <br />
          {"AS THEY ARE DELIGHTFUL".split(" ").map((word, i) => (
            <span
              key={`l2-${i}`}
              className="stagger-word"
              style={{ "--stagger-delay": `${(i + 3) * 0.08}s` }}
            >
              {word}&nbsp;
            </span>
          ))}
        </h2>
        <div className="product-carousel__navigation">
          <button type="button" className="carousel-arrow" onClick={previous} aria-label="Previous product">
            <span>←</span>
          </button>
          <button type="button" className="carousel-arrow carousel-arrow--filled" onClick={next} aria-label="Next product">
            <span>→</span>
          </button>
        </div>
      </div>

      <div className="product-carousel__viewport" ref={viewportRef}>
        <div
          className={`product-carousel__track ${isDragging ? "product-carousel__track--dragging" : ""}`}
          ref={trackRef}
          style={{ transform: `translateX(-${trackOffset}px)` }}
          onPointerDown={handlePointerDown}
          onPointerMove={handlePointerMove}
          onPointerUp={endDrag}
          onPointerLeave={endDrag}
        >
          {products.map((product, index) => {
            const isActive = hovered === index;
            return (
              <article
                className={`product-card ${isActive ? "is-active" : ""}`}
                key={product.id}
                onMouseEnter={() => setHovered(index)}
                onMouseLeave={() => setHovered(null)}
              >
                <div className="product-card__visual" style={{ "--accent": product.accent }}>
                  <span className="product-card__blob" />
                  <img src={product.image} alt={product.name} className="product-card__image" draggable={false} />
                </div>
                <h3>{product.name}</h3>
                <div className={`quick-add-stage ${isActive ? "is-active" : ""}`}>
                  <button type="button" className="quick-add-pill" onClick={() => setHovered(index)}>
                    QUICK ADD
                  </button>
                  <button
                    type="button"
                    className="quick-add-morph"
                    onClick={() => setHovered(index)}
                    aria-label={`Add ${product.name}`}
                  >
                    <svg className="quick-add-arrow" viewBox="0 0 24 24" fill="none">
                      <path d="M7 17 L17 7 M8 7 H17 V16" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" />
                    </svg>
                  </button>
                </div>
              </article>
            );
          })}
        </div>
      </div>
    </section>
  );
}
